<template>
  <div class="text-to-image-panel">
    <!-- 1. 标题区域 -->
    <div class="panel-header">
      <div class="panel-title">{{ t('generateImage') }}</div>
      <p class="panel-description">{{ t('selectStyleToGenerate') }}</p>
    </div>

    <!-- 2. 提示词输入 -->
    <div class="form-section">
      <label class="form-label">{{ t('prompt') }}</label>
      <p class="form-help">{{ t('promptDescription') }}</p>
      <el-input
        v-model="formData.prompt"
        type="textarea"
        :placeholder="t('promptPlaceholderImage')"
        :rows="4"
        class="prompt-input"
      />
    </div>

    <!-- 3. 模型选择 -->
    <div class="form-section">
      <label class="form-label">{{ t('model') }}</label>
      <p class="form-help">{{ t('modelDescription') }}</p>
          <OptionSelector 
            v-model="formData.model" 
            :type="'media'" 
            :placeholder="t('selectModel')"
            :show-radio="true"
            :show-description="true"
          />
    </div>

    <!-- 4. 清晰度选择 -->
    <div class="form-section">
      <label class="form-label">{{ t('resolution') }}</label>
      <div class="resolution-group">
        <div 
          v-for="item in resolutionOptionsRef" 
          :key="item.value" 
          class="resolution-option"
          :class="{ 'active': formData.resolution === item.value }"
          @click="formData.resolution = item.value"
        >
          {{ item.label }}
        </div>
      </div>
    </div>

    <!-- 5. 图片比例选择 -->
    <div class="form-section">
      <label class="form-label">{{ t('imageDimensions') }}</label>
      <p class="form-help">{{ t('imageDimensionsDescription') }}</p>
      <RatioSelector 
        v-model="formData.ratio"
        :type="'image'"
      />
    </div>

    <!-- 6. Seed选项 -->
    <div class="form-section seed-section-box">
      <OptionalSeedInput
        v-model="formData.seed"
        :title="t('seed')"
        :description="t('seedDescription')"
        :placeholder="t('seedPlaceholder')"
        @expand-change="showAdvancedOptions = $event"
      />
    </div>

    <!-- 7. 生成按钮 -->
    <div class="form-actions">
      <el-button
        :loading="isGenerating"
        @click="onGenerateClick"
        :disabled="isButtonDisabled"  
         class="generate-button"
         :class="{'disabled': isButtonDisabled}"
        block
      >
        <l-img w="18px" h="18px" src="/static/images/picture-icon.png"></l-img>
        {{ t('generateImage') }}
      </el-button>
    </div>
  </div>
</template>

<script setup>
// 引入区域
import { ref, computed, onMounted, onUnmounted, onBeforeUnmount } from 'vue';
import { ElMessage } from 'element-plus';
import { t } from "@/language/index";
import OptionSelector from '@/components/business/components/option-selector.vue';
import RatioSelector from '@/components/business/components/ratio-selector.vue';
import OptionalSeedInput from '@/components/business/components/optional-seed-input.vue';
import LImg from '@/components/l-img.vue';
import router from '@/router';
import { apiGeneration } from '@/api/api-generation';
import { resolutionOptions } from '@/types/panel-options';
import { addTaskToPolling, TaskType } from '@/presenter/media-task-polling';
import { mediaTaskEventBus, clearMediaTaskEventListeners } from '@/presenter/media-task-events';

// emits区域
const emit = defineEmits(['generate-success', 'generate-error', 'generate-create', 'loading']);

// 变量区域
const resolutionOptionsRef = ref(resolutionOptions);
const resolutionMap = {
    'standard': 512,
    'hd': 768,
    'ultra-hd': 1024
};

// 响应式变量
const formData = ref({
    prompt: '',
    model: '',
    resolution: '',
    ratio: '',
    seed: ''
});
const isGenerating = ref(false);
const showAdvancedOptions = ref(false);
// 当前任务ID，用于事件过滤
const currentTaskId = ref(null);

// 计算属性区域
const isButtonDisabled = computed(() => {
    return !formData.value.prompt || 
           !formData.value.model || 
           !formData.value.resolution || 
           !formData.value.ratio;
});

// 点击事件区域
const onGenerateClick = async () => {
  try {
    emit('generate-create');
    emit('loading', true,null);
    const result = await handleGenerate();
    
    // 设置路由meta并添加到轮询管理器
    const meta = router.currentRoute.value.meta;
    meta.taskId = result.taskId;
    meta.type = TaskType.IMAGE;
    addTaskToPolling(result.taskId, TaskType.IMAGE);
    
    // 设置当前任务ID
    currentTaskId.value = result.taskId;
  } catch (error) {
    emit('loading', false,null);
    emit('generate-error', error);
    currentTaskId.value = null;
  }
};

// 处理任务完成事件
const handleTaskCompleted = (res) => {
  if (res && res.taskId === currentTaskId.value) {
    emit('generate-success', res);
    isGenerating.value = false;
    currentTaskId.value = null;
  }
};

// 处理任务失败事件
const handleTaskFailed = (res) => {
  if (res && res.taskId === currentTaskId.value) {
    emit('generate-error', res);
    isGenerating.value = false;
    currentTaskId.value = null;
  }
};

// 处理任务状态更新事件
const handleTaskStatusUpdate = (res) => {
  if (res && res.taskId === currentTaskId.value) {
    console.log(`Progress: ${res.res.progress}%`);
    emit('loading', true, res.res.estimated_time || null);
  }
};

// 业务逻辑区域


const handleGenerate = async () => {
    isGenerating.value = true;
    try {
        // 准备请求数据 - 只传入新接口需要的字段
        const requestData = {
            prompt: formData.value.prompt.trim(),
            negative_prompt: '', // 负面提示词
            model: formData.value.model
        };

        // 只有XMIND-G-IMAGEN-3模型时才传入aspect_ratio
        if (formData.value.model === 'XMIND-G-IMAGEN-3') {
            requestData.aspect_ratio = formData.value.ratio;
        }

        // 调用真实的API
        const result = await apiGeneration.textToImage(requestData);
        return {
            taskId: result.task_id,
            requestData
        };
        
    } catch (error) {
        isGenerating.value = false;
        console.error('AI Media generate image failed:', error);
        ElMessage.error(t('generateFailed'));
        throw error;
    }
};

const toggleAdvancedOptions = () => {
    showAdvancedOptions.value = !showAdvancedOptions.value;
};

const resetForm = () => {
    formData.value = {
        prompt: '',
        model: '',
        resolution: '',
        ratio: '',
        seed: ''
    };
    showAdvancedOptions.value = false;
};

// 数据解析区域
const getWidthFromResolution = (resolution, ratio) => {
    const baseSize = resolutionMap[resolution] || 512;
    
    // 根据比例调整 - 处理所有支持的图片比例
    switch(ratio) {
        case '2:3': return Math.round(baseSize * 2 / 3);
        case '3:2': return Math.round(baseSize * 3 / 2);
        case '1:1': return baseSize;
        case '16:9': return Math.round(baseSize * 16 / 9);
        case '21:9': return Math.round(baseSize * 21 / 9);
        case '9:16': return Math.round(baseSize * 9 / 16);
        case '9:21': return Math.round(baseSize * 9 / 21);
        case '4:5': return Math.round(baseSize * 4 / 5);
        case '5:4': return Math.round(baseSize * 5 / 4);
        case '3:4': return Math.round(baseSize * 3 / 4);
        case '4:3': return Math.round(baseSize * 4 / 3);
        default: return baseSize; // 默认1:1
    }
};

const getHeightFromResolution = (resolution, ratio) => {
    const baseSize = resolutionMap[resolution] || 512;
    
    // 根据比例调整 - 处理所有支持的图片比例
    switch(ratio) {
        case '2:3': return Math.round(baseSize * 2 / 3);
        case '3:2': return Math.round(baseSize * 3 / 2);
        case '1:1': return baseSize;
        case '16:9': return Math.round(baseSize * 16 / 9);
        case '21:9': return Math.round(baseSize * 21 / 9);
        case '9:16': return Math.round(baseSize * 16 / 9);
        case '9:21': return Math.round(baseSize * 21 / 9);
        case '4:5': return Math.round(baseSize * 5 / 4);
        case '5:4': return Math.round(baseSize * 5 / 4);
        case '3:4': return Math.round(baseSize * 3 / 4);
        case '4:3': return Math.round(baseSize * 4 / 3);
        default: return baseSize; // 默认1:1
    }
};

const getConfigSummary = () => {
    return {
        model: formData.value.model,
        resolution: formData.value.resolution,
        ratio: formData.value.ratio,
        hasPrompt: !!formData.value.prompt.trim(),
        hasSeed: !!formData.value.seed,
        promptLength: formData.value.prompt.length
    };
};

// 周期函数区域
onMounted(() => {
  // 绑定媒体任务事件监听器（只绑定一次）
  mediaTaskEventBus.on('task-completed', handleTaskCompleted);
  mediaTaskEventBus.on('task-failed', handleTaskFailed);
  mediaTaskEventBus.on('task-status-update', handleTaskStatusUpdate);
});

onBeforeUnmount(() => {
  // 清理事件监听器（只清理一次）
  clearMediaTaskEventListeners();
});

onUnmounted(() => {
  // 清除路由meta中的taskId
  router?.currentRoute?.value?.meta ? router.currentRoute.value.meta.taskId = null : null;
});
</script>

