<template>
    <layout-make-media :main-title="t('textToImage')" :example-title="t('exampleTitle')">
        <!-- 左上区域：生成配置面板 -->
        <template #left-top>
            <TextToImagePanel 
                @generate-success="handleGenerateSuccess" 
                @generate-error="handleGenerateError"
                @generate-create="handleGenerateCreate"
                @loading="handleLoading" 
            />
        </template>

        <!-- 右上区域：生成结果展示 -->
        <template #right-top>
            <div class="result-panel">
                <media-generate-result :media-type="MEDIA_TYPES.IMAGE" :operation-type="IMAGE_OPERATIONS.GENERATE"
                                       :result-state="currentState" :media-data="sampleMediaData"
                                       :estimatedTime="estimatedTime" @action="handleAction">
                </media-generate-result>
            </div>
        </template>

        <!-- 底部区域：示例展示 -->
        <template #bottom>
            <bottom-image-video :comType="EXAMPLE_TYPES.IMAGE" />
        </template>
    </layout-make-media>
</template>

<script setup>
import { ref, onMounted } from 'vue';
import { ElMessage } from 'element-plus';
import { useI18n } from 'vue-i18n';
import LayoutMakeMedia from '@/components/layout/media-make.vue';
import TextToImagePanel from './panel/left-panel.vue';
import MediaGenerateResult from '@/components/business/media-generate-result.vue';
import { IMAGE_OPERATIONS, MEDIA_TYPES } from '@/types/media-tool';
import BottomImageVideo from '@/components/produce-media/image-video.vue';
import { EXAMPLE_TYPES } from '@/types/common';
import { handleMediaAction } from '@/utils/dialogMethod/media-action-handler.js';
import { routerTo } from '@/router/navigation.js';
import { ROUTER_PATHS } from '@/router/constants.js';
import { useMediaGenerationStore } from '@/store/modules/media-generation';

const { t } = useI18n();
const mediaStore = useMediaGenerationStore();

const isGenerating = ref(false);
const estimatedTime = ref(null);
const layoutMakeMedia = ref(null);
/*
* 生成结果相关参数
* currentState 当前状态: empty, loading, success, error
* sampleMediaData 示例媒体数据: 图片数据
*/
const currentState = ref('empty');
const sampleMediaData = ref({
    url: '',
    seed: '',
    media_id: ''
});


// 处理任务完成
const handleGenerateSuccess = (result) => {
    const res = result.result.media_list;
    sampleMediaData.value = {
        url: res[0].file_url,
        seed: res[0]?.seed || '',
        media_id: res[0]?.id || ''
    };
    currentState.value = 'success';
};

const handleAction = (action) => {
    // 使用通用的媒体操作处理器
    handleMediaAction(action, sampleMediaData.value, {
        onConfirm: (actionType, result) => {
            mediaStore.setGenerationResult(actionType, { imageUrl: result?.data?.url || '' });
            switch (actionType) {
                case IMAGE_OPERATIONS.DOWNLOAD:
                    // 下载逻辑已在 handleMediaAction 中处理
                    break;
                case IMAGE_OPERATIONS.ENHANCE:
                    // TODO 临时拦截
                    ElMessage.warning('Unsupported Operation !!!');
                    break;
                    // 增强图片 - 跳转到图片增强页面
                    // const imageUrl = mediaStore.getGenerationResult(IMAGE_OPERATIONS.ENHANCE);
                    // routerTo(ROUTER_PATHS.IMAGE_ENHANCEMENT);
                    // break;
                case IMAGE_OPERATIONS.EDIT:
                    // TODO 临时拦截
                    ElMessage.warning('Unsupported Operation !!!');
                    break;
                    // 编辑图片 - 跳转到图片编辑页面
                    // routerTo(ROUTER_PATHS.IMAGE_EDITOR, {
                    //     imageUrl: sampleMediaData.value.url,
                    //     seed: sampleMediaData.value.seed,
                    //     source: 'text-to-image'
                    // });
                    // break;
                case IMAGE_OPERATIONS.TO_VIDEO:
                    // 转视频 - 保存图片数据到Pinia并跳转到图片转视频页面
                    mediaStore.setGenerationResult(IMAGE_OPERATIONS.TO_VIDEO, {
                        imageUrl: sampleMediaData.value.url,
                        seed: sampleMediaData.value.seed,
                        mediaId: sampleMediaData.value.media_id,
                        source: 'text-to-image'
                    });
                    routerTo(ROUTER_PATHS.IMAGE_TO_VIDEO);
                    break;
                case IMAGE_OPERATIONS.ENLARGE:
                    // TODO 临时拦截
                    ElMessage.warning('Unsupported Operation !!!');
                    break;
                    // 放大图片 - 跳转到图片放大页面
                    // routerTo(ROUTER_PATHS.IMAGE_UPSCALER, {
                    //     imageUrl: sampleMediaData.value.url,
                    //     seed: sampleMediaData.value.seed,
                    //     source: 'text-to-image'
                    // });
                    // break;
                default:
                    console.warn('Unknown action type:', actionType);
                    break;
            }
        },
        onCancel: (actionType, result) => {
            console.log(`${actionType} operation cancelled:`, result);
        }
    });
};

// 处理生成错误
const handleGenerateError = (error) => {
    console.error('Image generation failed:', error);
    isGenerating.value = false;
    currentState.value = 'empty';
    ElMessage.error(t('generateFailed'));
};

//开始生成
const handleGenerateCreate = () => {
    isGenerating.value = true;
    currentState.value = 'loading';
    layoutMakeMedia.value.scrollTo({
        top: 0,
        behavior: 'smooth'
    });
};

// 处理生成loading
const handleLoading = (loading,time) => {
  isGenerating.value = loading;
  estimatedTime.value = time;
};

// 组件挂载时初始化
onMounted(() => {
    layoutMakeMedia.value = document.querySelector('.layout-make-media');
});
</script>

